<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getNavigationMenuContext, getNavigationMenuItemContext } from './navigation-menu-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; keepMounted?: boolean; ref?: HTMLDivElement | null; } let { children, keepMounted = false, ref = $bindable(null), ...rest }: Props = $props(); const navigation = getNavigationMenuContext(); const item = getNavigationMenuItemContext(); let open = $derived(navigation.value === item.value);</script>{#if keepMounted || open}<div bind:this={ref} {...rest} id={item.contentId} aria-labelledby={item.triggerId} hidden={!open} data-open={open ? '' : undefined}>{@render children?.()}</div>{/if}
